import * as OTPAuth from "otpauth";
import QRCode from "qrcode";

/*
 * Two-factor authentication with TOTP (RFC 6238): 6-digit codes that change every 30 seconds,
 * generated by an authenticator app (Google Authenticator, Microsoft Authenticator, ...).
 * Every user has their own secret, stored in users.totp_secret.
 */

const ISSUER = "9antra";
const PERIOD = 30;
const CODE_RE = /^\d{6}$/;

function totpFor(secretBase32, label = "") {
  return new OTPAuth.TOTP({
    issuer: ISSUER,
    label,
    algorithm: "SHA1", // what authenticator apps support everywhere
    digits: 6,
    period: PERIOD,
    secret: OTPAuth.Secret.fromBase32(secretBase32),
  });
}

/** New random secret (160 bits, base32). */
export function generateSecret() {
  return new OTPAuth.Secret({ size: 20 }).base32;
}

/** otpauth:// URI and a QR code (PNG data URL) to scan with an authenticator app. */
export async function enrolmentData(secretBase32, email) {
  const otpauthUrl = totpFor(secretBase32, email).toString();
  const qrCodeDataUrl = await QRCode.toDataURL(otpauthUrl, { margin: 1, width: 220 });
  return { otpauthUrl, qrCodeDataUrl };
}

/**
 * Check a 6-digit code. Accepts the previous, current and next 30-second step (clock drift).
 * Returns the matched time step, or null. A step <= lastStep is refused: a code is valid only once.
 */
export function verifyCode(code, secretBase32, { lastStep = null, timestamp = Date.now() } = {}) {
  const token = typeof code === "string" ? code.replace(/\s+/g, "") : "";
  if (!CODE_RE.test(token) || !secretBase32) return null;
  const totp = totpFor(secretBase32);
  const delta = totp.validate({ token, timestamp, window: 1 });
  if (delta === null) return null;
  const step = Math.floor(timestamp / 1000 / PERIOD) + delta;
  if (lastStep !== null && lastStep !== undefined && step <= Number(lastStep)) return null;
  return step;
}

/** Current code for a secret (tests and local tooling only). */
export function currentCode(secretBase32, timestamp = Date.now()) {
  return totpFor(secretBase32).generate({ timestamp });
}
